<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rezervasyonlarım</title><style>body{font-family:system-ui;background:#f6f8f6;color:#26332b;margin:0}.wrap{max-width:1000px;margin:35px auto;padding:0 18px}.item{background:white;border:1px solid #e7ece8;border-radius:13px;padding:18px;margin:12px 0;display:flex;justify-content:space-between;gap:15px}.muted{color:#6d796f}.tag{background:#eef5ef;padding:6px 10px;border-radius:20px;font-size:12px;height:max-content}@media(max-width:600px){.item{display:block}}</style></head><body><main class="wrap"><h1>Rezervasyonlarım</h1><p class="muted">Tüm rezervasyon talepleriniz ve durumları.</p><?php foreach($bookings as $booking): ?><article class="item"><div><strong><?= e($booking['title']) ?></strong><p class="muted"><?= e($booking['city']) ?> · <?= e(date('d.m.Y',strtotime($booking['check_in']))) ?> – <?= e(date('d.m.Y',strtotime($booking['check_out']))) ?> · <?= (int)$booking['guests'] ?> misafir</p><small><?= e($booking['booking_code']) ?></small></div><div><span class="tag"><?= e($booking['status']) ?></span><p><strong><?= e(number_format((float)$booking['total'],0,',','.')) ?> <?= e($booking['currency']) ?></strong></p></div></article><?php endforeach; ?><?php if(!$bookings): ?><p>Henüz rezervasyonunuz yok.</p><?php endif; ?><p><a href="/account/notifications">Bildirimler</a> · <a href="/">Yeni konaklama keşfet</a></p></main></body></html>